// Ambil item RSS hari ini yang judulnya berisi jadwal pemadaman.
const xml = $input.first().json.data || '';
const hariIni = new Date(Date.now() + 8 * 36e5).toISOString().slice(0, 10); // WITA
const items = [...xml.matchAll(/<item>([\s\S]*?)<\/item>/g)].map(m => {
  const t = k => ((m[1].match(new RegExp(`<${k}[^>]*>([\\s\\S]*?)<\\/${k}>`)) || [])[1] || '').replace(/<!\[CDATA\[|\]\]>/g, '').trim();
  return { judul: t('title'), url: t('link'), terbit: new Date(t('pubDate')) };
}).filter(i => /^https?:\/\//.test(i.url) && /jadwal|pemadaman|padam/i.test(i.judul) && /banjarmasin|kalsel|banjar|batola/i.test(i.judul)
  && new Date(i.terbit.getTime() + 8 * 36e5).toISOString().slice(0, 10) === hariIni);
return items.slice(0, 6).map(i => ({ json: { ...i, terbit: i.terbit.toISOString() } }));

// Lewati artikel yang sudah pernah diproses (sumber_url sudah ada di antrean).
const sudah = new Set($('Baca antrean (artikel lama)').all().map(r => r.json.sumber_url).filter(Boolean));
return $('Saring berita hari ini').all().filter(i => !sudah.has(i.json.url));

// Bersihkan HTML artikel menjadi teks polos (maks 12.000 karakter) untuk dibaca AI.
return $input.all().map((it, i) => {
  const html = String(it.json.data || '');
  const teks = html.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').slice(0, 12000);
  const asal = $('Saring berita hari ini').all()[i]?.json || {};
  return { json: { teks, sumber_url: asal.url, judul: asal.judul } };
}).filter(x => x.json.teks.length > 400);

const kelompok = $('Ambil kelompok.json').first().json;
const daftar = (Array.isArray(kelompok) ? kelompok : kelompok.data || []).map(k => `${k.kode} (ULP ${k.ulp || 'Lambung Mangkurat'}): ${k.teks}`).join('\n');
return $('Jadikan teks').all().map(it => ({ json: { sumber_url: it.json.sumber_url, masuk_via: 'berita', body: {
  model: $env.PANTAU_AI_MODEL || 'gpt-4o-mini', temperature: 0, response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: `Ekstrak jadwal pemadaman PLN UP3 Banjarmasin (hanya ULP Lambung Mangkurat dan ULP Ahmad Yani) dari artikel berita. Jawab HANYA JSON:
{"entri":[{"ulp":"Lambung Mangkurat|Ahmad Yani","jenis":"terjadwal|darurat","tanggal":"YYYY-MM-DD","mulai":"HH:MM","selesai":"HH:MM","blok":[{"teks":"<salin daftar wilayah>","kode":"<kode kelompok yang cocok atau BARU>"}],"alasan":"<ringkas>"}],"catatan":"<keraguan>"}
Abaikan ULP lain (Banjarbaru, Martapura, dst). Jangan menebak; kosongkan entri bila artikel tidak memuat jadwal ULP tersebut.
Kelompok yang dikenal:
${daftar}` },
    { role: 'user', content: it.json.teks } ] } } }));

const out = [];
$input.all().forEach((res, i) => {
  const meta = $('Siapkan permintaan AI').all()[i]?.json || {};
  let o; try { o = JSON.parse(res.json.choices?.[0]?.message?.content || '{}'); } catch { return; }
  (o.entri || []).forEach(e => out.push({ json: {
    id: `${e.ulp === 'Ahmad Yani' ? 'ay-' : ''}${e.tanggal}-${String(e.mulai).replace(':', '')}`, ulp: e.ulp, jenis: e.jenis || 'terjadwal',
    tanggal: e.tanggal, mulai: e.mulai, selesai: e.selesai, kelompok: (e.blok || []).map(b => b.kode || 'BARU').join(','),
    teks_wilayah: (e.blok || []).map(b => b.teks).join(' || '), alasan: e.alasan || '', poster: '', sumber_url: meta.sumber_url,
    status: 'menunggu', catatan_verifikator: 'dari berita (sumber sekunder) — cocokkan dengan pengumuman resmi PLN. ' + (o.catatan || ''), masuk_via: 'berita' } }));
});
return out;

// Kunci unik lintas sumber: ULP + tanggal + jam + kelompok (atau teks wilayah yang dinormalkan).
const norm = s => String(s || '').toLowerCase().replace(/\b(jl|jalan|gg|gang|komp|komplek|kp|dan|sekitarnya|sebagian)\b\.?/g, ' ').replace(/[^a-z0-9]+/g, ' ').trim();
const kunciDari = r => [String(r.ulp || '').toLowerCase().replace(/\s+/g, ''), r.tanggal, String(r.mulai).slice(0, 5), String(r.selesai).slice(0, 5),
  (r.kelompok && !/BARU|\?/.test(r.kelompok)) ? String(r.kelompok).split(',').map(s => s.trim()).sort().join('+') : norm(r.teks_wilayah).split(' ').sort().slice(0, 12).join('+')].join('|');

const ada = new Set(), sumber = new Set();
for (const r of $('Baca antrean (cek duplikat)').all()) { const j = r.json; if (j.kunci) ada.add(j.kunci); else if (j.tanggal) ada.add(kunciDari(j)); if (j.sumber_url) sumber.add(j.sumber_url); }
const keluar = [];
for (const it of $('Jadikan baris antrean').all()) {
  const r = it.json; r.kunci = kunciDari(r);
  if (ada.has(r.kunci)) continue;            // jadwal sama sudah ada (dari sumber mana pun)
  ada.add(r.kunci); keluar.push({ json: r });
}
return keluar;
